questionvariables.text:
var: x;
rand1: rand_with_step(13, 19, 1);
rand2: rand_with_step(-7, 1, 1);
rand3: rand_with_step(2, 3, 1);
f1: (rand1*var+rand2)/rand3;
rand4: rand_with_prohib(-9, 4, [0]);
rand5: rand_with_step(-8, 8, 1);
f2: rand4*var+rand5;
f3: (rand1*var+rand2);
f4: rand1+rand3;
rand6: rand_with_prohib(-10, 4, [0]);
rand7: rand1/rand3;
f5: var*rand7;
f6: var*(sqrt(rand1))+rand1;

corbase:[f3];
wrongbase: [f1, f2,f4,f5,f6];
mcq:multiselqn(corbase, 1, wrongbase, 3);

